import{_ as t,o as s,c as i,a4 as n}from"./chunks/framework.BE47AOxC.js";const h=JSON.parse(`{"title":"ADR-0022 — Usine à sites : ce qu'un provisionnement crée, hérite, partage — et ce qu'il ne touche pas","description":"Extrait de docs/adr/0022-usine-a-sites-perimetre-du-provisionnement.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0022 — Usine à sites : ce qu'un provisionnement crée, hérite, partage — et ce qu'il ne touche pas","description":"Extrait de docs/adr/0022-usine-a-sites-perimetre-du-provisionnement.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0022-usine-a-sites-perimetre-du-provisionnement.md","filePath":"developpeurs/adr/0022-usine-a-sites-perimetre-du-provisionnement.md"}`),a={name:"developpeurs/adr/0022-usine-a-sites-perimetre-du-provisionnement.md"};function r(o,e,d,l,c,u){return s(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="adr-0022--usine-à-sites--ce-quun-provisionnement-crée-hérite-partage--et-ce-quil-ne-touche-pas" tabindex="-1">ADR-0022 — Usine à sites : ce qu&#39;un provisionnement crée, hérite, partage — et ce qu&#39;il ne touche pas <a class="header-anchor" href="#adr-0022--usine-à-sites--ce-quun-provisionnement-crée-hérite-partage--et-ce-quil-ne-touche-pas" aria-label="Permalink to &quot;ADR-0022 — Usine à sites : ce qu&#39;un provisionnement crée, hérite, partage — et ce qu&#39;il ne touche pas {#adr-0022--usine-à-sites--ce-quun-provisionnement-crée-hérite-partage--et-ce-quil-ne-touche-pas}&quot;">​</a></h1><p><strong>Date :</strong> 21 août 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> CDC_CMS_AI_Native_v1.1 §9.3 ; Epic E10, plan d&#39;action §12.6 ; complète l&#39;ADR-0015 (captcha) et l&#39;ADR-0010 (plugins par organisation)</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Le CDC décrit l&#39;usine à sites par un modèle déclaratif :</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#024C1A;--shiki-dark:#72F088;">site_template</span><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">:</span></span>
<span class="line"><span style="--shiki-light:#024C1A;--shiki-dark:#72F088;">  name</span><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">: </span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;">&quot;Commune type&quot;</span></span>
<span class="line"><span style="--shiki-light:#024C1A;--shiki-dark:#72F088;">  copy</span><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">:   [</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;">pages</span><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">, </span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;">menus</span><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">, </span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;">blocks</span><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">, </span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;">listing_configs</span><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">, </span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;">forms</span><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">]</span></span>
<span class="line"><span style="--shiki-light:#024C1A;--shiki-dark:#72F088;">  share</span><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">:  [</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;">media_library</span><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">, </span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;">taxonomies</span><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">]        </span><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># référence, pas copie</span></span>
<span class="line"><span style="--shiki-light:#024C1A;--shiki-dark:#72F088;">  reset</span><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">:  [</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;">content_entries</span><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">, </span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;">users</span><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">, </span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;">analytics_id</span><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">]</span></span>
<span class="line"><span style="--shiki-light:#024C1A;--shiki-dark:#72F088;">  override_fields</span><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">: [</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;">name</span><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">, </span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;">domain</span><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">, </span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;">logo</span><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">, </span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;">favicon</span><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">, </span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;">color_primary</span><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">, </span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;">color_secondary</span><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">]</span></span></code></pre></div><p>Ces catégories sont celles d&#39;un CMS générique. Confrontées au schéma réel de ce Core, elles posent trois questions que le CDC ne tranche pas, et qu&#39;un provisionnement silencieux aurait tranchées à sa place :</p><ol><li><strong>Deux catégories ne correspondent à aucune entité de ce dépôt.</strong> Il n&#39;existe pas de table de menus, ni de médiathèque ; un bloc n&#39;est pas une entité (il vit dans <code>pages.layout</code>, E2) ; <code>listing_configs</code> et <code>forms</code> sont des colonnes de <code>content_types</code> (E3, E11), qui appartient à l&#39;<strong>organisation</strong> et non au site.</li><li><strong>Le CDC est muet sur les plugins.</strong> Un site provisionné dans une organisation où le plugin Commentaires est installé doit-il l&#39;activer ? Et le formulaire déclaré par un Content Type doit-il s&#39;ouvrir sur le nouveau site ?</li><li><strong>« Clés captcha » figure dans l&#39;identité surchargeable d&#39;un site</strong>, alors que l&#39;ADR-0015 a fait du captcha un réglage d&#39;<strong>instance</strong> — un vérificateur branché en code, un refus bruyant s&#39;il manque.</li></ol><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><h3 id="1-chaque-catégorie-du-modèle-reçoit-un-traitement-nommé-dans-le-rapport-de-provisionnement" tabindex="-1">1. Chaque catégorie du modèle reçoit un traitement <strong>nommé dans le rapport de provisionnement</strong> <a class="header-anchor" href="#1-chaque-catégorie-du-modèle-reçoit-un-traitement-nommé-dans-le-rapport-de-provisionnement" aria-label="Permalink to &quot;1. Chaque catégorie du modèle reçoit un traitement **nommé dans le rapport de provisionnement** {#1-chaque-catégorie-du-modèle-reçoit-un-traitement-nommé-dans-le-rapport-de-provisionnement}&quot;">​</a></h3><p>Le provisionnement rend un compte rendu où chaque catégorie porte l&#39;une des quatre actions <code>copied</code> / <code>inherited</code> / <code>shared</code> / <code>reset</code>, et une phrase qui dit pourquoi. Une catégorie qui ne ferait rien sans le dire serait le « réglage qui ne fait rien » que ce Core refuse partout ailleurs.</p><table tabindex="0"><thead><tr><th>Catégorie</th><th>Action</th><th>Motif</th></tr></thead><tbody><tr><td><code>pages</code></td><td><code>copied</code></td><td>Recopiées avec projection des blocs (règle 7) puis <strong>revalidation intégrale</strong> par <code>validate_page_layout</code>.</td></tr><tr><td><code>blocks</code></td><td><code>copied</code></td><td>Pas d&#39;entité propre : copier les pages copie les blocs. Le rapport le dit.</td></tr><tr><td><code>menus</code></td><td><strong>refusé à la validation du modèle</strong></td><td>Aucune entité menu dans ce Core. Un administrateur doit l&#39;apprendre en écrivant son modèle, pas en ouvrant le site provisionné.</td></tr><tr><td><code>listing_configs</code>, <code>forms</code></td><td><code>inherited</code></td><td>Colonnes de <code>content_types</code>, qui est organisation-scopé : le nouveau site en dispose sans copie — donc sans rien à resynchroniser plus tard.</td></tr><tr><td><code>media_library</code></td><td><code>shared</code></td><td>Les médias sont désignés par identifiant dans les blocs : une page copiée désigne les mêmes. C&#39;est très exactement le « référence, pas copie » du CDC.</td></tr><tr><td><code>taxonomies</code></td><td><code>shared</code></td><td>Les termes du site modèle sont recréés sur le nouveau site <strong>avec leur provenance</strong> (ADR-0021), donc reconnus comme les mêmes termes par la règle 6.</td></tr><tr><td><code>content_entries</code></td><td><code>reset</code></td><td>Sens même d&#39;un site neuf. Il recevra, s&#39;il y a lieu, les contenus que les règles de partage (CDC §9.1) lui destinent.</td></tr><tr><td><code>users</code></td><td><code>reset</code></td><td>Rien à remettre à zéro : comptes de back-office (E6) et comptes usagers (E12) appartiennent à l&#39;organisation. Le rapport le dit plutôt que de compter zéro sans expliquer.</td></tr><tr><td><code>analytics_id</code></td><td><code>reset</code></td><td>Seule valeur dont la recopie serait activement nuisible : deux sites qui remontent sous le même identifiant produisent des chiffres faux <strong>pour les deux</strong>.</td></tr></tbody></table><h3 id="2-override_fields-est-un-contrat-vérifié-pas-un-commentaire" tabindex="-1">2. <code>override_fields</code> est un contrat vérifié, pas un commentaire <a class="header-anchor" href="#2-override_fields-est-un-contrat-vérifié-pas-un-commentaire" aria-label="Permalink to &quot;2. \`override_fields\` est un contrat vérifié, pas un commentaire {#2-override_fields-est-un-contrat-vérifié-pas-un-commentaire}&quot;">​</a></h3><p>Un provisionnement dont l&#39;identité fournie ne couvre pas tous les champs déclarés est <strong>refusé</strong> (422). Sans ce contrôle, la liste n&#39;aurait décrit aucune obligation, et un site aurait pu partir en ligne avec le logo et les couleurs de la commune voisine. <code>subdomain</code> est obligatoirement dans la liste : il est unique en base, il ne peut donc jamais s&#39;hériter.</p><p>Un site provisionné <strong>n&#39;est jamais le site principal</strong> : le site amiral est celui dont on part, et en désigner un second changerait le sens des quatre modes de partage de toute l&#39;organisation — ce qui ne peut pas être l&#39;effet de bord d&#39;une création de site.</p><h3 id="3-les-plugins-ne-sont-ni-activés-ni-désactivés-par-un-provisionnement" tabindex="-1">3. Les plugins ne sont ni activés ni désactivés par un provisionnement <a class="header-anchor" href="#3-les-plugins-ne-sont-ni-activés-ni-désactivés-par-un-provisionnement" aria-label="Permalink to &quot;3. Les plugins ne sont ni activés ni désactivés par un provisionnement {#3-les-plugins-ne-sont-ni-activés-ni-désactivés-par-un-provisionnement}&quot;">​</a></h3><p>L&#39;état d&#39;installation d&#39;un plugin est une donnée <strong>de l&#39;organisation</strong> (ADR-0010, <code>OrganizationPlugin</code>). Un site provisionné hérite donc des plugins de son organisation, ni plus ni moins, et l&#39;usine n&#39;invente <strong>aucune</strong> activation par site. Conséquences directes et voulues :</p><ul><li>une page copiée contenant un bloc de plugin se revalide correctement, puisque le registre de blocs de l&#39;organisation contient ce plugin ;</li><li>un formulaire (<code>form_config</code> sur un Content Type, ADR-0014) est disponible sur le nouveau site dès sa création, sans acte d&#39;activation — un Content Type appartient à l&#39;organisation, et son formulaire avec lui ;</li><li>un réglage de panneau apporté par un plugin (« Autoriser les commentaires ») reste soumis à l&#39;installation <strong>de l&#39;organisation</strong>, exactement comme avant.</li></ul><p>Introduire une activation par site aurait signifié un second mécanisme d&#39;installation, avec ses divergences propres, pour une question que le CDC ne pose pas.</p><h3 id="4-captcha--la-clé-publique-est-du-site-le-fournisseur-et-le-secret-restent-de-linstance" tabindex="-1">4. Captcha : la clé publique est du site, le fournisseur et le secret restent de l&#39;instance <a class="header-anchor" href="#4-captcha--la-clé-publique-est-du-site-le-fournisseur-et-le-secret-restent-de-linstance" aria-label="Permalink to &quot;4. Captcha : la clé publique est du site, le fournisseur et le secret restent de l&#39;instance {#4-captcha--la-clé-publique-est-du-site-le-fournisseur-et-le-secret-restent-de-linstance}&quot;">​</a></h3><p><code>sites.captcha_site_key</code> existe, est surchargeable par l&#39;usine, et est servie par le descripteur public d&#39;un formulaire quand l&#39;appel désigne un site (<code>GET /public/forms/{key}?site_id=…</code>). Le <strong>fournisseur</strong> (<code>CAPTCHA_PROVIDER</code>) et le vérificateur branché en code restent d&#39;instance : brancher un vérificateur est un acte d&#39;exploitation (ADR-0015), et une installation sans fournisseur refuse toute soumission, quel que soit le site.</p><p>Ce partage n&#39;est pas arbitraire : la clé de site est <strong>publique</strong>, elle est faite pour être servie au navigateur ; la clé secrète appairée ne l&#39;est pas. La déposer dans <code>sites</code> aurait déplacé un secret d&#39;exploitation de l&#39;environnement vers la base de données — c&#39;est-à-dire vers ses sauvegardes, ses exports et ses réplicas. <strong>Limite assumée et écrite ici</strong> : une clé de site propre à chaque site ne fonctionne donc qu&#39;avec un fournisseur dont le secret couvre plusieurs clés. Sinon, la clé d&#39;instance s&#39;applique, et le champ reste ce que le CDC en dit — un élément d&#39;identité du site.</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Accepter <code>menus</code> et ne rien faire</strong></td><td>Le modèle serait devenu un document d&#39;intention. Un administrateur aurait découvert l&#39;absence de menus sur le site provisionné, c&#39;est-à-dire au pire moment.</td></tr><tr><td><strong>Créer une entité menu au passage</strong></td><td>Hors CDC pour cet Epic, et une navigation est un sujet à part entière (arborescence, libellés i18n, restrictions d&#39;accès héritées). L&#39;improviser dans une usine à sites l&#39;aurait figée.</td></tr><tr><td><strong>Écrire les pages copiées directement en base</strong> (plus rapide, pas de revalidation)</td><td>C&#39;est précisément le scénario que l&#39;ADR-0019 nomme comme la raison d&#39;être de la validation serveur : « un seul bloc Localiser par page » et les règles de composition d&#39;E2 deviendraient contournables par le premier provisionnement — c&#39;est-à-dire là où une page se duplique sur toute une organisation.</td></tr><tr><td><strong>Copier les <code>content_types</code> du site modèle</strong> (pour rendre <code>listing_configs</code>/<code>forms</code> réellement « copiés »)</td><td>Un Content Type est organisation-scopé, et le dupliquer par site casserait le prérequis du CDC §9.2 (schémas rigoureusement identiques entre sites) au moment même où l&#39;usine crée le site qui devra les partager.</td></tr><tr><td><strong>Activer par site les plugins installés sur l&#39;organisation</strong></td><td>Second mécanisme d&#39;installation, seconde source de vérité, et une question sans énoncé dans le CDC.</td></tr><tr><td><strong>Stocker la clé secrète de captcha par site</strong></td><td>Déplace un secret d&#39;exploitation vers la base et ses sauvegardes, pour un gain que seul un déploiement multi-fournisseur justifierait.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Le provisionnement produit un site <strong>consultable immédiatement</strong> — sa page d&#39;accueil se rend, sans bloc vide ni lien mort — ce que la recette vérifie en appelant le rendu du nouveau site.</li><li>Ce que l&#39;usine n&#39;a pas fait est <strong>écrit dans sa réponse</strong>, catégorie par catégorie, y compris les blocs retirés au titre de la règle 7.</li><li>Aucune règle de composition n&#39;est contournée par le provisionnement : la promesse de l&#39;ADR-0019 est tenue à l&#39;endroit exact où elle était en jeu.</li></ul><p><strong>Négatives</strong></p><ul><li>Un modèle de site déclarant <code>menus</code> est refusé, alors que c&#39;est la valeur d&#39;exemple du CDC. Le message d&#39;erreur nomme les catégories connues ; c&#39;est un refus explicite plutôt qu&#39;un silence, mais c&#39;est un écart avec l&#39;exemple du CDC, assumé ici.</li><li><code>listing_configs</code>/<code>forms</code> en <code>inherited</code> peut surprendre qui attend une copie indépendante : modifier la vue liste de l&#39;organisation modifie celle de tous ses sites. C&#39;est le comportement correct au regard du prérequis de mutualisation, et le rapport le dit explicitement.</li><li>Le captcha par site reste conditionné au fournisseur, ce qui rend le champ partiellement décoratif sur une installation mono-clé. L&#39;alternative — un secret en base — était pire.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] <code>SiteTemplate</code>, <code>SiteIdentity</code>, <code>provision_site</code> (<code>apps/api/app/multisite/factory.py</code>), route <code>POST /api/v1/sites/provision</code>.</li><li>[x] Colonnes d&#39;identité sur <code>sites</code> + index unique partiel <code>uq_sites_main_per_organization</code> (migration <code>0014_multisite_propagation</code>).</li><li>[x] <code>GET /api/v1/public/forms/{key}?site_id=…</code> sert la clé publique du site (<code>apps/api/app/api/public_forms.py</code>).</li><li>[x] Recette : <code>test_usine_a_sites_produit_un_site_fonctionnel</code>, <code>test_la_cle_captcha_publique_est_celle_du_site</code>, <code>test_un_seul_site_principal_par_organization</code> (<code>apps/api/tests/test_multisite.py</code>).</li><li>[x] Admin (Nuxt, hors périmètre backend) : écran de provisionnement présentant le rapport, catégorie par catégorie, et les blocs retirés. → <strong>Close</strong> par <code>7638d60</code> (28/08/2026) : <code>apps/admin/pages/multisite/sites.vue:445-495</code> affiche le rapport après provisionnement — blocs de contenus chauds retirés, étapes, pages créées. Cochée le 26/09/2026 (audit du 26/09, SUIVI-4).</li></ul>`,30)])])}const g=t(a,[["render",r]]);export{h as __pageData,g as default};
